\begin{enumerate}
\item 由两角和公式，\( f(x)=2\sin\left( \omega x+\varphi \right) \). 对于 \( y=2\sin\left( \omega x+\varphi \right) \)，最小正周期为 \( \frac{2\pi}{\omega} \). 由题意得 \( \frac{2\pi}{\omega}=\pi \)，所以 \( \omega=2 \). 于是 \( f(x)=2\sin\left( 2x+\varphi \right) \). 由 \( f(0)>0 \) 得 \( 2\sin \varphi>0 \). 又 \( \left| \varphi \right|<\frac{\pi}{2} \)，所以 \( 0<\varphi<\frac{\pi}{2} \). 再由 \( f\left( \frac{\pi}{4} \right)=1 \)，得 \( 2\sin\left( \frac{\pi}{2}+\varphi \right)=1 \)，即 \( 2\cos \varphi=1 \). 所以 \( \cos \varphi=\frac{1}{2} \). 结合 \( 0<\varphi<\frac{\pi}{2} \)，得 \( \varphi=\frac{\pi}{3} \). 因此 \( \omega=2 \)，\( \varphi=\frac{\pi}{3} \).
\item 又 \( f'(x)=4\cos\left( 2x+\frac{\pi}{3} \right) \). 函数单调递减时，\( f'(x)<0 \)，所以 \( \cos\left( 2x+\frac{\pi}{3} \right)<0 \)，即 \( \frac{\pi}{2}+2k\pi<2x+\frac{\pi}{3}<\frac{3\pi}{2}+2k\pi \)，从而 \( \frac{\pi}{12}+k\pi<x<\frac{7\pi}{12}+k\pi \).
其中 \( k\in\Z \). 所以 \( f(x) \) 的单调递减区间为 \( \left( \frac{\pi}{12}+k\pi,\frac{7\pi}{12}+k\pi \right) \)（\( k\in\Z \)）.
\end{enumerate}

